export const SOLUTIONS: Record<number, string[]> = {
  5: SOLUTIONS_RAW[5].filter((w) => WORD_SETS[5].has(w)),
  6: SOLUTIONS_RAW[6].filter((w) => WORD_SETS[6].has(w)),
};

export function isValidWord(word: string): boolean {
  return WORD_SETS[word.length]?.has(word) ?? false;
}

export function randomWord(len: WordLength): string {
  const pool = SOLUTIONS[len];
  return pool[Math.floor(Math.random() * pool.length)];
}
